/** Reset all browser state */
Cypress.Commands.add('resetState', () => {
  cy.clearAllCookies()
  cy.clearAllLocalStorage()
  cy.clearAllSessionStorage()
})

/** Seed application via API */
Cypress.Commands.add('seedData', (scenario) => {
  cy.request({
