/** Stub all auth requests to bypass real authentication */
Cypress.Commands.add('stubAuth', (user = {}) => {
  const defaultUser = {
    id: 1,
    name: 'Test User',
    email: 'test@example.com',
    role: 'user',
    ...user,
  }

  cy.intercept('POST', '/api/auth/login', {
